import pandas as pd,numpy as np,gzip,scipy.io as sio
from scipy.optimize import nnls
from scipy.stats import fisher_exact
sc=pd.read_csv('spatial_q_sc_counts.csv',index_col=0); meta=pd.read_csv('spatial_q_sc_metadata.csv',index_col=0);pos=pd.read_csv('tissue_positions.csv');S=sio.mmread(gzip.open('matrix.mtx.gz','rt')).tocsr().toarray().T.astype(float)
types=list(meta.cell_type.unique());X=sc.values.astype(float);means=np.array([X[meta.cell_type.values==t].mean(0) for t in types]);sets=[]
for j in range(6):
 o=np.max(np.delete(means,j,axis=0),0);ss=np.log2((means[j]+.1)/(o+.1));sets.append(np.argsort(ss)[-50:])
use=np.unique(np.concatenate(sets));co=np.array([nnls(means[:,use].T,S[i,use])[0] for i in range(900)]);pres=co>.25
# map id by row col
idx={(int(p.array_row),int(p.array_col)):i for i,p in pos.iterrows()}
# neighbors 8 grid; each target-other pair directed
for neighname, offsets in [('4',[(1,0),(-1,0),(0,1),(0,-1)]),('8',[(a,b) for a in [-1,0,1] for b in [-1,0,1] if (a,b)"'!=(0,0)]),('"'radius2',[(a,b) for a in range(-2,3) for b in range(-2,3) if (a,b)"'!=(0,0) and a*a+b*b<=4])]:
 print('"'\\n',neighname)
 target=[]
 for (r,c),i in idx.items():
  if pres[i,0]:
   for dr,dc in offsets:
    j=idx.get((r+dr,c+dc));
    if j is not None:target.append(j)
 target=np.array(target)
 # target list has repeats due each neighbor; compare all spots / perhaps target focal neighborhood
 for j,t in enumerate(types[1:],1):
  count=(pres[target,j]).sum(); total=len(target); pnear=count/total; pglob=pres[:,j].mean();
  # focal spots with neighbor type vs non? use permutation z / binomial rough
  print(t,'neighbor slots',total,'presence',count,round(pnear,3),'global',round(pglob,3),'ratio',round(pnear/pglob,2))
# focal tumor spot has other type same spot, and immediate neighbor union
print('\\nco-occurrence in same tumor-containing spots')
for j,t in enumerate(types[1:],1): print(t,pres[pres[:,0],j].sum(),pres[pres[:,0],j].mean(),'global',pres[:,j].mean())
